import db from "../db.server";

export async function createQuestion(
  quizId: string,
  shop: string,
  data: {
    type: string;
    title: string;
    description?: string;
    required?: boolean;
    imageUrl?: string | null;
    settings?: string;
  }
) {
  // Verify quiz ownership
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  const count = await db.question.count({ where: { quizId } });

  return db.question.create({
    data: {
      quizId,
      type: data.type,
      title: data.title,
      description: data.description ?? null,
      required: data.required ?? true,
      position: count,
      imageUrl: data.imageUrl ?? null,
      settings: data.settings ?? JSON.stringify({}),
    },
    include: { answers: { orderBy: { position: "asc" } } },
  });
}

export async function updateQuestion(
  id: string,
  quizId: string,
  shop: string,
  data: {
    title?: string;
    type?: string;
    description?: string | null;
    required?: boolean;
    settings?: string;
  }
) {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  return db.question.update({
    where: { id },
    data,
  });
}

export async function deleteQuestion(
  id: string,
  quizId: string,
  shop: string
): Promise<void> {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");
  await db.question.delete({ where: { id } });

  // Reorder remaining questions
  const remaining = await db.question.findMany({
    where: { quizId },
    orderBy: { position: "asc" },
  });
  await Promise.all(
    remaining.map((q, i) =>
      db.question.update({ where: { id: q.id }, data: { position: i } })
    )
  );
}

export async function reorderQuestions(
  quizId: string,
  shop: string,
  questionIds: string[]
): Promise<void> {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  await Promise.all(
    questionIds.map((id, position) =>
      db.question.update({ where: { id }, data: { position } })
    )
  );
}

export async function createAnswer(
  questionId: string,
  quizId: string,
  shop: string,
  data: {
    text: string;
    imageUrl?: string | null;
    score?: number;
    productTags?: string[];
    metadata?: string;
  }
) {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  const count = await db.answer.count({ where: { questionId } });

  return db.answer.create({
    data: {
      questionId,
      text: data.text,
      imageUrl: data.imageUrl ?? null,
      score: data.score ?? 0,
      productTags: JSON.stringify(data.productTags ?? []),
      position: count,
      metadata: data.metadata ?? JSON.stringify({}),
    },
  });
}

export async function updateAnswer(
  id: string,
  questionId: string,
  quizId: string,
  shop: string,
  data: {
    text?: string;
    score?: number;
    productTags?: string[];
  }
) {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  return db.answer.update({
    where: { id },
    data: {
      text: data.text,
      score: data.score,
      ...(data.productTags !== undefined
        ? { productTags: JSON.stringify(data.productTags) }
        : {}),
    },
  });
}

export async function deleteAnswer(
  id: string,
  questionId: string,
  quizId: string,
  shop: string
): Promise<void> {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  // Suppress unused param lint — kept for ownership verification signature parity
  void questionId;

  await db.answer.delete({ where: { id } });
}

export async function saveQuestionsAndAnswers(
  quizId: string,
  shop: string,
  questions: Array<{
    id?: string;
    title: string;
    type: string;
    description?: string | null;
    required: boolean;
    position: number;
    settings?: string;
    logic?: string;
    imageUrl?: string | null;
    answers: Array<{
      id?: string;
      text: string;
      imageUrl?: string | null;
      score: number;
      productTags: string[];
      position: number;
      metadata?: string;
    }>;
  }>
) {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  // Delete all existing questions (cascade deletes answers)
  await db.question.deleteMany({ where: { quizId } });

  // Create new ones in order
  for (const q of questions) {
    await db.question.create({
      data: {
        quizId,
        title: q.title,
        type: q.type,
        description: q.description ?? null,
        required: q.required,
        position: q.position,
        settings: q.settings ?? JSON.stringify({}),
        logic: q.logic ?? JSON.stringify({}),
        imageUrl: q.imageUrl ?? null,
        answers: {
          create: q.answers.map((a) => ({
            text: a.text,
            imageUrl: a.imageUrl ?? null,
            score: a.score,
            productTags: JSON.stringify(a.productTags),
            position: a.position,
            metadata: a.metadata ?? JSON.stringify({}),
          })),
        },
      },
    });
  }
}
